20 |   --color-primary: var(--primary);
21 |   --color-primary-foreground: var(--primary-foreground);
22 |   --color-secondary: var(--secondary);
23 |   --color-secondary-foreground: var(--secondary-foreground);
24 |   --color-muted: var(--muted);
25 |   --color-muted-foreground: var(--muted-foreground);
26 |   --color-accent: var(--accent);
27 |   --color-accent-foreground: var(--accent-foreground);
28 |   --color-destructive: var(--destructive);
29 |   --color-destructive-foreground: var(--destructive-foreground);
30 |   --color-success: var(--success);
31 |   --color-success-foreground: var(--success-foreground);
32 |   --color-border: var(--border);
33 |   --color-input: var(--input);
34 |   --color-ring: var(--ring);
35 | 
36 |   /* Radius scale (derived from one --radius so the whole feel shifts together) */
37 |   --radius-sm: calc(var(--radius) - 4px);
38 |   --radius-md: calc(var(--radius) - 2px);
39 |   --radius-lg: var(--radius);
40 |   --radius-xl: calc(var(--radius) + 4px);
41 | 
42 |   /* Elevation: subtle, neutral, slightly cool. Borders lead; shadows support. */
43 |   --shadow-xs: 0 1px 2px 0 oklch(0.2 0.04 285 / 0.06);
44 |   --shadow-sm: 0 1px 3px 0 oklch(0.2 0.04 285 / 0.08), 0 1px 2px -1px oklch(0.2 0.04 285 / 0.08);
45 |   --shadow-md: 0 4px 12px -2px oklch(0.2 0.04 285 / 0.10);
46 |   --shadow-lg: 0 12px 32px -8px oklch(0.2 0.04 285 / 0.14);
47 | 
48 |   /* Motion: restrained and snappy */
49 |   --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
50 |   --duration-fast: 150ms;
51 |   --duration: 200ms;
52 | }
53 | 
54 | :root {
55 |   /* Highest-identity single decision: medium radius, friendly but precise. */
56 |   --radius: 0.625rem;
57 | 
58 |   /* Brand ramp (modern, gender-neutral blue) */
59 |   --brand-50:  oklch(0.970 0.018 255);
60 |   --brand-100: oklch(0.930 0.040 255);
61 |   --brand-300: oklch(0.780 0.110 255);
62 |   --brand-500: oklch(0.560 0.180 255); /* primary */
63 |   --brand-600: oklch(0.500 0.185 255); /* hover/active */
64 |   --brand-700: oklch(0.440 0.160 255);
65 |   --brand-900: oklch(0.300 0.110 255);
66 | 
67 |   /* Light mode (this is the mode we perfect). Neutrals are cool gray. */
68 |   --background: oklch(0.990 0.002 260);
69 |   --foreground: oklch(0.220 0.010 260);
70 |   --card: oklch(1 0 0);
71 |   --card-foreground: oklch(0.220 0.010 260);
72 |   --popover: oklch(1 0 0);
73 |   --popover-foreground: oklch(0.220 0.010 260);
74 |   --primary: var(--brand-500);
75 |   --primary-foreground: oklch(0.990 0 0);
76 |   --secondary: oklch(0.965 0.004 260);
77 |   --secondary-foreground: oklch(0.300 0.010 260);
78 |   --muted: oklch(0.965 0.004 260);
79 |   --muted-foreground: oklch(0.520 0.012 260);
80 |   --accent: oklch(0.950 0.022 255);
81 |   --accent-foreground: var(--brand-700);
82 |   --destructive: oklch(0.580 0.210 25);
83 |   --destructive-foreground: oklch(0.990 0 0);
84 |   --success: oklch(0.600 0.150 150);
85 |   --success-foreground: oklch(0.990 0 0);
86 |   --border: oklch(0.920 0.005 260);
87 |   --input: oklch(0.920 0.005 260);
88 |   --ring: var(--brand-500);
89 | }
90 | 
91 | .dark {
92 |   /* Near-black, faintly cool-blue. Deep canvas with a measured blue accent
93 |      (present, not neon) so it reads well in dark mode without being intrusive.
94 |      Cards lift just enough off the bg; borders (not shadows) define structure. */
95 |   --background: oklch(0.155 0.012 255);
96 |   --foreground: oklch(0.970 0.005 255);
97 |   --card: oklch(0.200 0.014 255);
98 |   --card-foreground: oklch(0.970 0.005 255);
99 |   --popover: oklch(0.200 0.014 255);
100 |   --popover-foreground: oklch(0.970 0.005 255);
101 |   --primary: oklch(0.640 0.155 255);
102 |   --primary-foreground: oklch(0.990 0 0);
103 |   --secondary: oklch(0.235 0.014 255);
104 |   --secondary-foreground: oklch(0.970 0.005 255);
105 |   --muted: oklch(0.235 0.014 255);
106 |   --muted-foreground: oklch(0.720 0.020 255);
107 |   --accent: oklch(0.320 0.045 255);
108 |   --accent-foreground: oklch(0.970 0.005 255);
109 |   --destructive: oklch(0.640 0.190 25);
110 |   --destructive-foreground: oklch(0.990 0 0);
111 |   --success: oklch(0.680 0.160 150);
112 |   --success-foreground: oklch(0.150 0.020 255);
113 |   --border: oklch(0.275 0.014 255);
114 |   --input: oklch(0.275 0.014 255);
115 |   --ring: oklch(0.640 0.155 255);
116 | }
117 | 
118 | @layer base {
119 |   * {
120 |     border-color: var(--border);
121 |   }
122 |   body {
123 |     background-color: var(--background);
124 |     color: var(--foreground);
125 |     font-family: var(--font-sans);
126 |     -webkit-font-smoothing: antialiased;
127 |     text-rendering: optimizeLegibility;
128 |   }
129 |   /* The one typographic rule: headings are tight-tracked; body never exceeds 70ch. */
130 |   h1, h2, h3, h4 {
131 |     letter-spacing: -0.02em;
132 |     text-wrap: balance;
133 |   }
134 |   p {
135 |     max-width: 70ch;
136 |   }
137 | }
