1 | <!DOCTYPE html>
2 | <html lang="en">
3 | <head>
4 |   <meta charset="UTF-8" />
5 |   <meta name="viewport" content="width=device-width, initial-scale=1.0" />
6 |   <title>BugSleuth — Incident Investigation</title>
7 |   <script src="/static/script.js" defer></script>
8 |   <style>
9 |     *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
10 | 
11 |     body {
12 |       font-family: -apple-system, "Segoe UI", system-ui, sans-serif;
13 |       font-size: 14px;
14 |       line-height: 1.6;
15 |       background: #0f1117;
16 |       color: #e2e8f0;
17 |       min-height: 100vh;
18 |       display: flex;
19 |       flex-direction: column;
20 |     }
21 | 
22 |     /* ── Safety notice banner ── */
23 |     .safety-notice {
24 |       display: flex;
25 |       align-items: flex-start;
26 |       gap: 8px;
27 |       background: #0c1a2e;
28 |       border: 1px solid #1e3a5f;
29 |       border-radius: 6px;
30 |       padding: 10px 12px;
31 |       font-size: 11px;
32 |       color: #7cb4f0;
33 |       line-height: 1.5;
34 |     }
35 |     .safety-notice .safety-icon {
36 |       flex-shrink: 0;
37 |       font-size: 13px;
38 |       margin-top: 1px;
39 |     }
40 |     .safety-notice strong { color: #93c5fd; }
41 | 
42 |     /* ── Layout ── */
43 |     header {
44 |       background: #1a1d27;
45 |       border-bottom: 1px solid #2d3148;
46 |       padding: 14px 32px;
47 |       display: flex;
48 |       align-items: center;
49 |       gap: 12px;
50 |     }
51 |     header h1 { font-size: 18px; font-weight: 700; color: #a78bfa; }
52 |     header span { font-size: 12px; color: #64748b; }
53 | 
54 |     main {
55 |       display: grid;
56 |       grid-template-columns: 380px 1fr;
57 |       gap: 0;
58 |       flex: 1;
59 |     }
60 | 
61 |     /* ── Sidebar (input) ── */
62 |     aside {
63 |       background: #1a1d27;
64 |       border-right: 1px solid #2d3148;
65 |       padding: 24px 20px;
66 |       display: flex;
67 |       flex-direction: column;
68 |       gap: 16px;
69 |       overflow-y: auto;
70 |     }
71 | 
72 |     aside h2 { font-size: 13px; color: #94a3b8; text-transform: uppercase; letter-spacing: .06em; }
73 | 
74 |     label { font-size: 13px; color: #cbd5e1; display: block; margin-bottom: 4px; }
75 | 
76 |     textarea, input[type="file"] {
77 |       width: 100%;
78 |       background: #0f1117;
79 |       border: 1px solid #2d3148;
80 |       border-radius: 6px;
81 |       color: #e2e8f0;
82 |       padding: 8px 10px;
83 |       font-family: "Consolas", "Fira Code", monospace;
84 |       font-size: 12px;
85 |       resize: vertical;
86 |     }
87 |     textarea { min-height: 80px; }
88 |     textarea:focus, input[type="file"]:focus { outline: none; border-color: #7c3aed; }
89 | 
90 |     .btn {
91 |       display: block;
92 |       width: 100%;
93 |       padding: 10px;
94 |       border: none;
95 |       border-radius: 6px;
96 |       font-size: 14px;
97 |       font-weight: 600;
98 |       cursor: pointer;
99 |       transition: opacity .15s;
100 |     }
101 |     .btn:hover { opacity: .85; }
102 |     .btn-primary   { background: #7c3aed; color: #fff; }
103 |     .btn-secondary { background: #1e3a5f; color: #93c5fd; border: 1px solid #2563eb; }
104 |     .btn-download  { background: #14532d; color: #4ade80; border: 1px solid #166534; }
105 |     .btn:disabled  { opacity: .4; cursor: not-allowed; }
106 | 
107 |     .divider { border: none; border-top: 1px solid #2d3148; }
108 | 
109 |     /* ── Report panel ── */
110 |     #report {
