179 |     }
180 | 
181 |     /* ── Evidence-to-verdict flow ── */
182 |     .flow-row {
183 |       display: flex;
184 |       align-items: stretch;
185 |       gap: 0;
186 |       overflow-x: auto;
187 |       margin-bottom: 4px;
188 |     }
189 |     .flow-node {
190 |       flex: 1;
